import React from "react";
import { motion } from "framer-motion";
import { BRAND } from "./Content";
import { Sparkles, ArrowDown, Crown } from "lucide-react";

export default function Hero({ onOpenQuote }) {
  const scrollToCollections = () => {
    document.getElementById("collections")?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <section id="top" className="hero">
      {/* Background Image */}
      <div
        className="hero-bg"
        style={{
          backgroundImage: "url('/images/hero.jpg')",
        }}
      />

      {/* Overlay */}
      <div className="hero-overlay" />

      {/* Content */}
      <div className="hero-content">
        <div className="mx-auto">
          {/* Location Badge */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="flex items-center gap-3 mb-6 lg:mb-8"
          >
            <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
            <span className="text-xs sm:text-sm tracking-[0.25em] uppercase font-semibold" style={{ color: "#d4af37" }}>
              Ludhiana, Punjab | Pan India Delivery
            </span>
          </motion.div>

          {/* Main Title */}
          <motion.h1
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4 }}
            className="hero-title"
          >
            D SAJAWAT
          </motion.h1>

          {/* Tagline */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.5 }}
            className="flex items-center gap-3 mb-4 lg:mb-6"
          >
            <Crown size={22} color="#d4af37" />
            <p className="hero-tagline">{BRAND.tagline}</p>
          </motion.div>

          {/* Subtitle */}
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.6 }}
            className="hero-subtitle mb-8 lg:mb-10"
          >
            Premium fabrics for weddings & events. Trusted by India's top decorators with Pan India delivery.
          </motion.p>

          {/* CTA Buttons */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.7 }}
            className="flex flex-col sm:flex-row gap-3 lg:gap-4"
          >
            <button onClick={scrollToCollections} className="btn-primary">
              <Sparkles size={18} />
              <span>Explore Collections</span>
            </button>
            <button onClick={onOpenQuote} className="btn-secondary" style={{ background: "rgba(255,255,255,0.1)", color: "#fff", borderColor: "rgba(212,175,55,0.5)" }}>
              <span>Get a Quote</span>
            </button>
          </motion.div>

          {/* Feature Pills */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.8 }}
            className="flex flex-wrap gap-3 mt-8 lg:mt-12"
          >
            {["Premium Quality", "Pan India Delivery", "Bulk Orders"].map((text) => (
              <div
                key={text}
                className="px-4 py-2 lg:px-5 lg:py-2.5 rounded-full text-xs lg:text-sm font-medium"
                style={{ background: "rgba(255,255,255,0.15)", color: "#fff", border: "1px solid rgba(212,175,55,0.3)" }}
              >
                {text}
              </div>
            ))}
          </motion.div>
        </div>
      </div>

      {/* Scroll Indicator */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1.2 }}
        className="absolute bottom-6 lg:bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 cursor-pointer"
        onClick={scrollToCollections}
      >
        <span className="text-xs tracking-widest uppercase" style={{ color: "rgba(212,175,55,0.8)" }}>Scroll</span>
        <motion.div
          animate={{ y: [0, 8, 0] }}
          transition={{ duration: 1.5, repeat: Infinity }}
        >
          <ArrowDown size={22} color="#d4af37" />
        </motion.div>
      </motion.div>
    </section>
  );
}
